private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        Type abstractType = currentFrame[i];
        int typeTag = abstractType.getSort();
        switch (typeTag) {
            case Type.OBJECT:
                String typeInternalName = abstractType.getInternalName();
                stackMapTableEntries.add(new StackMapTableEntry(typeTag, LinkObject.forName(typeInternalName)));
                break;
            case Type.ARRAY:
                String elementTypeInternalName = ((ArrayType) abstractType).getDescriptor().substring(1);
                stackMapTableEntries.add(new StackMapTableEntry(typeTag, LinkObject.forName(elementTypeInternalName)));
                break;
            default:
                stackMapTableEntries.add(new StackMapTableEntry(typeTag, LinkObject.forType(abstractType)));
                break;
        }
    }
}

