  Map<String, String> charsetMap = new HashMap<>();
  charsetMap.put("UTF-8", "UTF-8");
  charsetMap.put("UTF-16", "UTF-16");
  charsetMap.put("ISO-8859-1", "ISO-8859-1");
  charsetMap.put("US-ASCII", "US-ASCII");
  charsetMap.put("ISO-8859-15", "ISO-8859-15");
  charsetMap.put("UTF-7", "UTF-7");
  charsetMap.put("UTF-16BE", "UTF-16BE");
  charsetMap.put("UTF-16LE", "UTF-16LE");
  charsetMap.put("UTF-32", "UTF-32");
  charsetMap.put("UTF-32BE", "UTF-32BE");
  charsetMap.put("UTF-32LE", "UTF-32LE");

  // if the charset is not recognized, return the original name
  if (!charsetMap.containsKey(charset)) {
    return charset;
  }

  // return the Java equivalent
  return charsetMap.get(charset);
}

