public static boolean unlink(ListNodeImpl<E> node){/** 
 * Remove the non null  {@code node} from the list. 
 */

	// If the node is null, don't do anything
	if (node == null) {
		return false;
	}

    // Get the head node
    ListNodeImpl<E> head = node.getHead();

    // Check if the node is the head node
    if (head == null) {
        head = node;
    }

    // Remove the node from the list
    while (node.hasNext()) {
        // Get the next node
        ListNodeImpl<E> next = node.getNext();

        // Check if the next node is the head node
        if (next == head.getNext()) {
            // Unlink the node
            head.setNext(node.getNext());
        } else {
            // Unlink the node
            node.setNext(next.getNext());
        }

        // Clear the node's links
        node.setLeft(null);
        node.setRight(null);
    }

    // Return true if the node was removed
    return true;
}

