public static <V, E> IsomorphicGraphMapping<V, E> identity (Graph<V, E> graph) {
    // Create a new mapping object
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>();
    // Add vertex mappings for all vertices in the graph
    for (V vertex : graph.vertexSet()) {
        mapping.addVertexMapping(vertex, vertex);
    }
    // Add edge mappings for all edges in the graph
    for (E edge : graph.edgeSet()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        mapping.addEdgeMapping(edge, new Pair(source, target));
    }
    return mapping;
}

