    // split the path and relativePath into lists of components
    List<String> pathList = new ArrayList<String>(Arrays.asList(path.split("/")));
    List<String> relativePathList = new ArrayList<String>(Arrays.asList(relativePath.split("/")));

    // iterate through the relativePathList and update the pathList accordingly
    for (String component : relativePathList) {
        if (component.equals("..")) {
            // if the component is "..", remove the last component from the pathList
            pathList.remove(pathList.size() - 1);
        } else if (!component.isEmpty()) {
            // if the component is not ".." or "", add it to the pathList
            pathList.add(component);
        }
    }

    // join the pathList into a single String
    return String.join("/", pathList);
}

