    if (appenderList == null) {
        return -1;
    }

    int count = 0;
    for (Appender appender : appenderList) {
        try {
            appender.doAppend(event);
            count++;
        } catch (Exception e) {
            // Do nothing, just log and move on to the next appender
            log.error("Error appending event to appender " + appender.getName(), e);
        }
    }

    return count;
}

