public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            threadSnapshot.setFile(file);
            threadSnapshot.setTimeRange(timeRanges);

            if (line.startsWith("[")) {
                // Parse the timestamp
                threadSnapshot.setStartTimestamp(parseTimestamp(line.substring(1)));
            } else if (line.startsWith("]")) {
                // Parse the duration
                threadSnapshot.setDuration(parseDuration(line.substring(1)));
            } else if (line.startsWith("T")) {
                // Parse the thread ID
                threadSnapshot.setThreadId(Integer.parseInt(line.substring(1)));
            } else if (line.startsWith("t")) {
                // Parse the thread name
                threadSnapshot.setThreadName(line.substring(1));
            } else if (line.startsWith("v")) {
                // Parse the median value
                threadSnapshot.setMedianValue(Double.parseDouble(line.substring(1)));
            } else if (line.startsWith("n")) {
                // Parse the number of samples
                threadSnapshot.setNumSamples(Integer.parseInt(line.substring(1)));
            }

            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}

