public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){

// Check if the input string is null or empty
if(str == null || str.length() == 0){
return lb;
}

// Create a new byte array to hold the utf8-encoded bytes
byte[] bytes = new byte[str.length()];

// Iterate through the input string and encode each character as utf8
for(int i = 0; i < str.length(); i++){
int codePoint = str.charAt(i);
if(Character.isSupplementaryCodePoint(codePoint)){
// Supplementary characters are encoded as a pair of surrogate characters
bytes[i++] = (byte) (0xD800 + (codePoint >> 10));
bytes[i] = (byte) (0xDC00 + (codePoint & 0x3FF));
}else{
bytes[i] = (byte) codePoint;
}
}

// Write the encoded bytes to the LinkedBuffer
lb.writeBytes(bytes);

return lb;
}

