public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    int b;
    do {
        // Read the next byte from the stream.
        b = in.read();
        if (b == -1) {
            // Check if the stream has ended before the Varint is fully read.
            if (shift >= 64) {
                throw new IOException("Failed to read a complete Varint from the stream.");
            }
            break;
        }
        // Append the bits to the result.
        result |= (((long) b & 0x7F) << shift);
        shift += 7;
    } while ((b & 0x80) != 0);
    return result;
}

